+export const PALETTE_MRU_LIMIT = 40;
+
+export function normalizePaletteText(value) {
+    return String(value || '').trim().toLowerCase();
+}
+
+export function tokenizePaletteQuery(value) {
+    return normalizePaletteText(value).split(/\s+/).map((item) => item.trim()).filter(Boolean);
+}
+
+export function includesAllPaletteTokens(haystack, tokens) {
+    if (!tokens.length) return true;
+    return tokens.every((token) => haystack.includes(token));
+}
+
+export function normalizeMruEntries(raw) {
+    const list = Array.isArray(raw)
+        ? raw
+        : raw && Array.isArray(raw.entries)
+            ? raw.entries
+            : [];
+
+    const byKey = new Map();
+    for (const entry of list) {
+        const isObject = entry && typeof entry === 'object';
+        const key = String(isObject ? entry.key : entry || '').trim();
+        if (!key) continue;
+
+        const existing = byKey.get(key);
+        const count = Math.max(1, Number(isObject ? entry.count : 1) || 1);
+        const lastUsedAt = Math.max(0, Number(isObject ? entry.lastUsedAt : 0) || 0);
+        byKey.set(key, {
+            key,
+            count: existing ? Math.max(existing.count, count) : count,
+            lastUsedAt: existing ? Math.max(existing.lastUsedAt, lastUsedAt) : lastUsedAt,
+        });
+    }
+
+    return Array.from(byKey.values())
+        .sort((a, b) => {
+            if (b.lastUsedAt !== a.lastUsedAt) return b.lastUsedAt - a.lastUsedAt;
+            if (b.count !== a.count) return b.count - a.count;
+            return a.key.localeCompare(b.key);
+        })
+        .slice(0, PALETTE_MRU_LIMIT);
+}
+
+export function updateMruEntries(entries, itemKey, now = Date.now()) {
+    const safeKey = String(itemKey || '').trim();
+    if (!safeKey) return normalizeMruEntries(entries);
+
+    const normalized = normalizeMruEntries(entries);
+    const existing = normalized.find((entry) => entry.key === safeKey);
+    const next = [
+        {
+            key: safeKey,
+            count: existing ? existing.count + 1 : 1,
+            lastUsedAt: Math.max(0, Number(now) || Date.now()),
+        },
+        ...normalized.filter((entry) => entry.key !== safeKey),
+    ];
+    return normalizeMruEntries(next);
+}
+
+export function derivePaletteContext(shell = {}) {
+    const workflowId = String(shell && shell.workflowId || '').trim();
+    const sessions = Array.isArray(shell && shell.sessions) ? shell.sessions : [];
+    const chatLog = Array.isArray(shell && shell.chatLog) ? shell.chatLog : [];
+    const sessionHydrationStatus = String(shell && shell.sessionHydrationStatus || '').trim();
+    const contexts = new Set(['global', 'system']);
+
+    if (workflowId) contexts.add('workflow');
+    if (sessions.length) contexts.add('session');
+    if (chatLog.length) contexts.add('chat');
+    if (sessionHydrationStatus === 'locked') contexts.add('locked-session');
+    if (workflowId && sessionHydrationStatus !== 'locked') contexts.add('active-workflow');
+
+    return {
+        workflowId,
+        hasWorkflow: Boolean(workflowId),
+        hasSessions: sessions.length > 0,
+        hasChat: chatLog.length > 0,
+        sessionHydrationStatus,
+        contexts: Array.from(contexts),
+    };
+}
+
+export function commandMatchesPaletteContext(command, paletteContext = {}) {
+    const required = Array.isArray(command && command.contexts)
+        ? command.contexts.map((item) => String(item || '').trim()).filter(Boolean)
+        : [];
+    if (!required.length) return true;
+
+    const available = new Set(
+        Array.isArray(paletteContext && paletteContext.contexts)
+            ? paletteContext.contexts.map((item) => String(item || '').trim()).filter(Boolean)
+            : ['global'],
+    );
+    return required.some((scope) => available.has(scope));
+}
+
+export function scorePaletteItem(item, query, queryTokens, mruEntry) {
+    const label = normalizePaletteText(item && item.label);
+    const id = normalizePaletteText(item && item.id);
+    const keywords = normalizePaletteText(item && item.keywords);
+    const haystack = `${label} ${id} ${keywords}`.trim();
+    if (!haystack) return Number.NEGATIVE_INFINITY;
+    if (!includesAllPaletteTokens(haystack, queryTokens)) return Number.NEGATIVE_INFINITY;
+
+    let score = Number(item && item.contextWeight) || 0;
+    const kind = String(item && item.kind || 'command');
+
+    if (!query) {
+        score += kind === 'command' ? 12 : 6;
+    } else {
+        if (haystack.startsWith(query)) score += 150;
+        if (label.startsWith(query)) score += 120;
+        if (id.startsWith(query)) score += 80;
+        if (label.includes(query)) score += 50;
+        if (id.includes(query)) score += 30;
+
+        for (const token of queryTokens) {
+            if (label.startsWith(token)) score += 20;
+            else if (label.includes(token)) score += 10;
+            if (id.startsWith(token)) score += 12;
+            else if (id.includes(token)) score += 6;
+            if (keywords.includes(token)) score += 4;
+        }
+    }
+
+    if (query.startsWith('/') && kind === 'command') {
+        score += 35;
+    }
+    if (
+        kind === 'session'
+        && queryTokens.some((token) => token === 'session' || token === 'workflow' || token === 'thread')
+    ) {
+        score += 22;
+    }
+
+    if (mruEntry) {
+        const rank = Math.max(0, Number(mruEntry.rank) || 0);
+        const count = Math.max(1, Number(mruEntry.count) || 1);
+        score += Math.max(0, 110 - (rank * 5));
+        score += Math.min(35, count * 5);
+    }
+
+    if (kind === 'session' && item.active) {
+        score += 12;
+    }
+    if (kind === 'session' && item.locked) {
+        score -= 4;
+    }
+
+    return score;
+}
+
+export function buildPaletteAnnouncement({ resultCount, selectedLabel, query }) {
+    const count = Math.max(0, Number(resultCount) || 0);
+    const prefix = query
+        ? `${count} result${count === 1 ? '' : 's'} for ${String(query).trim()}`
+        : `${count} palette result${count === 1 ? '' : 's'}`;
+    return selectedLabel ? `${prefix}. Selected ${selectedLabel}.` : `${prefix}.`;
+}
