+        workflowId: 'NeuralShell_QuickStart',
+        sessions: ['NeuralShell_QuickStart'],
+        chatLog: [{ role: 'user', content: '/status' }],
+        sessionHydrationStatus: 'ready',
+    });
+
+    assert.equal(context.hasWorkflow, true);
