+import {
+    CHRONO_EVENT_CHANGE_EVENT,
+    CHRONO_EVENT_STATUSES,
+    CHRONO_EVENT_STORAGE_KEY,
+    CHRONO_ITEM_TYPES,
+    CHRONO_SOURCES,
+} from './chronoTypes.js';
+
+function nowIso() {
+    return new Date().toISOString();
+}
+
+function makeId(prefix) {
+    return `${String(prefix || 'chrono')}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
+}
+
+function safeString(value, fallback = '') {
+    const next = String(value ?? '').trim();
+    return next || fallback;
+}
+
+function parseTime(value) {
+    const time = new Date(value).getTime();
+    return Number.isFinite(time) ? time : Number.NaN;
+}
+
+function dateToDeadlineDueAt(date) {
+    const safe = safeString(date);
+    if (!safe) return '';
+    if (safe.includes('T')) return new Date(safe).toISOString();
+    return new Date(`${safe}T23:59:00`).toISOString();
+}
+
+export function normalizeChronoEvent(record = {}) {
+    const started = parseTime(record.startAt);
+    const ended = parseTime(record.endAt);
+    const createdAt = safeString(record.createdAt, nowIso());
+    const startAt = Number.isFinite(started) ? new Date(started).toISOString() : '';
+    const endAt = Number.isFinite(ended) ? new Date(ended).toISOString() : startAt;
+    return {
+        id: safeString(record.id, makeId('event')),
+        type: CHRONO_ITEM_TYPES.EVENT,
+        title: safeString(record.title, 'Untitled event'),
+        description: safeString(record.description),
+        startAt,
+        endAt,
+        allDay: Boolean(record.allDay),
+        category: safeString(record.category),
+        location: safeString(record.location),
+        source: CHRONO_SOURCES.LOCAL,
+        sourceId: safeString(record.sourceId),
+        status: Object.values(CHRONO_EVENT_STATUSES).includes(record.status)
+            ? record.status
+            : CHRONO_EVENT_STATUSES.CONFIRMED,
+        reminders: Array.isArray(record.reminders) ? record.reminders : [],
+        createdAt,
+        updatedAt: safeString(record.updatedAt, createdAt),
+    };
+}
+
+export function loadChronoEvents() {
+    if (typeof window === 'undefined' || !window.localStorage) return [];
+    try {
+        const parsed = JSON.parse(window.localStorage.getItem(CHRONO_EVENT_STORAGE_KEY) || '[]');
+        if (!Array.isArray(parsed)) return [];
+        return parsed
+            .map(normalizeChronoEvent)
+            .filter((item) => item.title && item.startAt && item.endAt)
+            .sort((left, right) => left.startAt.localeCompare(right.startAt));
+    } catch {
+        return [];
+    }
+}
+
+export function saveChronoEvents(events = []) {
+    const normalized = (Array.isArray(events) ? events : [])
+        .map(normalizeChronoEvent)
+        .filter((item) => item.title && item.startAt && item.endAt)
+        .sort((left, right) => left.startAt.localeCompare(right.startAt));
+    if (typeof window !== 'undefined' && window.localStorage) {
+        try {
+            window.localStorage.setItem(CHRONO_EVENT_STORAGE_KEY, JSON.stringify(normalized));
+        } catch {
+            // best effort persistence
+        }
+    }
+    try {
+        window.dispatchEvent(new CustomEvent(CHRONO_EVENT_CHANGE_EVENT, { detail: normalized }));
+    } catch {
+        // best effort broadcast
+    }
+    return normalized;
+}
