+export function upsertChronoEvent(events = [], record = {}) {
+    const normalized = normalizeChronoEvent(record);
+    const current = (Array.isArray(events) ? events : []).map(normalizeChronoEvent);
+    const index = current.findIndex((item) => item.id === normalized.id);
+    if (index >= 0) {
